def semver_sort(versions):
    def parse_version(version):
        # Split by '+' to remove build metadata
        if '+' in version:
            version = version.split('+', 1)[0]

        # Split by '-' to separate pre-release
        if '-' in version:
            base, prerelease = version.split('-', 1)
        else:
            base = version
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = base.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease:
            identifiers = prerelease.split('.')
            prerelease_tuple = tuple(
                (0, int(ident)) if ident.isdigit() else (1, ident)
                for ident in identifiers
            )
        else:
            prerelease_tuple = None

        return (major, minor, patch, prerelease_tuple)

    def sort_key(item):
        index, version = item
        major, minor, patch, prerelease_tuple = parse_version(version)

        # Use (major, minor, patch) as primary key
        # For pre-release: None (no pre-release) sorts after a pre-release
        # So we use a tuple where presence of pre-release is second in sort order
        # and we use a special value to sort release versions last
        if prerelease_tuple is None:
            # Release version: sort after pre-release
            prerelease_key = (1,)
        else:
            # Pre-release version: sort before release
            prerelease_key = (0, prerelease_tuple)

        return (major, minor, patch, prerelease_key, index)

    sorted_items = sorted(enumerate(versions), key=sort_key)
    return [version for _, version in sorted_items]

